-- Generated by tools/build_action_data.py; do not edit.
return {["scripts/actions/spells/trust/rosulatia.lua"]={["Path"]="scripts/actions/spells/trust/rosulatia.lua",["SHA256"]="4407065ae3a9887a0277bd01defd5c9efec936672cb33b861b3fa5824bea7bf5",["Text"]="-----------------------------------\n-- Trust: Rosulatia\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/rughadjeen.lua"]={["Path"]="scripts/actions/spells/trust/rughadjeen.lua",["SHA256"]="193f55c3f9497a6f77af96bd534cb0ba609c3f56c64fad0feff45b2e143bc5cf",["Text"]="-----------------------------------\n-- Trust: Rughadjeen\n-- Possesses Fast Cast, Cure Potency Received +30%, Damage Taken -5%.\n-- He wields the Algol and so has an enfire effect and a 3% triple attack rate.\n-- Uses Holy Circle if the enemy is Undead.\n-- Will only cast Cure I - IV when a party member is below 75% (yellow) HP or asleep.\n-- Tries to use weapon skills at 1000 TP, but it is lower priority.\n-- Uses Chivalry at 50% MP if it's available.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.NASHMEIRA] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.GADALAR] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.NAJELITH] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.ZAZARG] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.MIHLI_ALIAPOH] = xi.trust.messageOffset.TEAMWORK_5\n    })\n\n    mob:addMod(xi.mod.FASTCAST, 30)\n    mob:addMod(xi.mod.CURE_POTENCY_RCVD, 30)\n    mob:addMod(xi.mod.TRIPLE_ATTACK, 3)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 20)\n    mob:addMod(xi.mod.MPP, 20)\n\n    local lvl = mob:getMainLvl()\n\n    -- Algol Additional Effect: Fire DMG, procs around 33%, dmg seems to be around 30 at lvl 99 from testing.\n    local potency =  utils.clamp(math.floor(lvl * 0.26), 3, 30)\n    mob:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    mob:addMod(xi.mod.ENSPELL_DMG, potency)\n    mob:addMod(xi.mod.ENSPELL_CHANCE, 33)\n\n    local lastSynergyBonus = 0\n    -- Dynamic modifier that checks party member list on tick to apply\n    mob:addListener('COMBAT_TICK', 'RUGHADJEEN_CTICK', function(mobArg)\n        local synergyMembers =\n        {\n            xi.magic.spell.MIHLI_ALIAPOH,\n            xi.magic.spell.GADALAR,\n            xi.magic.spell.ZAZARG,\n            xi.magic.spell.NAJELITH\n        }\n\n        local synergyCount = 0\n        local party = mobArg:getMaster():getPartyWithTrusts()\n\n        for _, member in pairs(party) do\n            if member:getObjType() == xi.objType.TRUST then\n                local trustId = member:getTrustID()\n                for _, sId in ipairs(synergyMembers) do\n                    if trustId == sId then\n                        synergyCount = synergyCount + 1\n                        break\n                    end\n                end\n            end\n        end\n\n        -- Determine what the bonus should be\n        -- When any other serpent generals are in the party, Rughadjeen has Damage Taken -29% while in combat with a foe.\n        local targetBonus = (synergyCount >= 1) and -2900 or 0\n        -- Only update if the state has changed\n        if targetBonus ~= lastSynergyBonus then\n            -- Subtract exactly what we added last time\n            mobArg:delMod(xi.mod.DMG, lastSynergyBonus)\n            -- Add the new bonus\n            mobArg:addMod(xi.mod.DMG, targetBonus)\n            -- Update lastSynergyBonus\n            lastSynergyBonus = targetBonus\n        end\n    end)\n\n    if lvl >= 5 then\n        mob:addGambit(ai.t.TARGET, { ai.c.IS_ECOSYSTEM, xi.ecosystem.UNDEAD }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HOLY_CIRCLE })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    if lvl >= 50 then\n        mob:addGambit(ai.t.SELF, { { ai.c.MPP_LT, 50 }, { ai.c.TP_GTE, 1000 } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CHIVALRY })\n    end\n\n    if lvl >= 75 then\n        mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DIVINE_EMBLEM })\n    end\n\n    mob:addGambit(ai.t.TARGET,     { ai.c.NOT_STATUS,   xi.effect.FLASH     }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH       })\n    mob:addGambit(ai.t.PARTY,      { ai.c.HPP_LT,       75                  }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.CURE  })\n    mob:addGambit(ai.t.PARTY_DEAD, { ai.c.MPP_GTE,      200                 }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.RAISE })\n    mob:addGambit(ai.t.TARGET,     { ai.c.IS_ECOSYSTEM, xi.ecosystem.UNDEAD }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HOLY        })\n    mob:addGambit(ai.t.PARTY,      { ai.c.STATUS,       xi.effect.SLEEP_I   }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE        })\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM, 1000)\n\n    mob:addListener('WEAPONSKILL_USE', 'RUGHADJEEN_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.VICTORY_BEACON_TRUST then -- Victory Beacon\n        -- Do not despair! The Goddess of Victory fights by our side!\n            if math.randomInt(1, 100) <= 33 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n            end\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/sakura.lua"]={["Path"]="scripts/actions/spells/trust/sakura.lua",["SHA256"]="ecfa3f05d07a688bf30b88df829a3522baf629085fa10b6ace1bc50b1826f802",["Text"]="-----------------------------------\n-- Trust: Sakura\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_REGEN,\n        subPower = mob:getMainLvl(),\n        subIcon = xi.effect.GEO_REGEN,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 4 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/selh_teus.lua"]={["Path"]="scripts/actions/spells/trust/selh_teus.lua",["SHA256"]="1f05136b712aad011f81cdfdc5e7461c464a3d0a0152c3a980e7a79cebab2e73",["Text"]="-----------------------------------\n-- Trust: Selh'teus\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/semih_lafihna.lua"]={["Path"]="scripts/actions/spells/trust/semih_lafihna.lua",["SHA256"]="1de41b503cf90932f1b10ffd06497710e31d5f630603c81f8fbedbd215a48360",["Text"]="-----------------------------------\n-- Trust: Semih Lafihna\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.STAR_SIBYL] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.AJIDO_MARUJIDO] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.BARRAGE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BARRAGE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SHARPSHOT }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SHARPSHOT })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.DOUBLE_SHOT }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DOUBLE_SHOT })\n\n    -- TODO: Stealth Shot not yet implemented\n    -- mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.STEALTH_SHOT })\n\n    mob:addListener('WEAPONSKILL_USE', 'SEMIH_LAFIHNA_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3490 then -- Stellar Arrow\n            -- I'll show you no quarter!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    -- Ranged Attack as much as possible (limited by 'weapon' delay)\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.RATTACK, 0, 0 })\n\n    mob:setAutoAttackEnabled(false)\n\n    -- Gets 252 TP per hit even at level 1, see https://www.bg-wiki.com/ffxi/BGWiki:Trusts#Semih_Lafihna\n    -- Using STP as a hack to ensure proper TP amount, as her delay is not that high on retail.\n    mob:addMod(xi.mod.STORETP, 86)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.LONG_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/shantotto.lua"]={["Path"]="scripts/actions/spells/trust/shantotto.lua",["SHA256"]="0bc9c39f935a0ea8355c9fbb4c2657c1bc3f99908139a45334a1ce6077f2fa3b",["Text"]="-----------------------------------\n-- Trust: Shantotto\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.SHANTOTTO_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.AJIDO_MARUJIDO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.STAR_SIBYL] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.KORU_MORU] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.KING_OF_HEARTS] = xi.trust.messageOffset.TEAMWORK_4\n    })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.MB_AVAILABLE, 0 }, { ai.r.MA, ai.s.MB_ELEMENT, xi.magic.spellFamily.NONE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.NONE }, 60)\n\n    local power = mob:getMainLvl() / 10\n    mob:addMod(xi.mod.MATT, power)\n    mob:addMod(xi.mod.MACC, power)\n    mob:addMod(xi.mod.HASTE_MAGIC, 1000) -- 10% Haste (Magic)\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/shantotto_ii.lua"]={["Path"]="scripts/actions/spells/trust/shantotto_ii.lua",["SHA256"]="e1a15367736d29cd5a557580d28d4c90cda109711b1a24fa11913c0531b14917",["Text"]="-----------------------------------\n-- Trust: Shantotto II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.SHANTOTTO)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addGambit(ai.t.TARGET, { ai.c.MB_AVAILABLE, 0 }, { ai.r.MA, ai.s.MB_ELEMENT, xi.magic.spellFamily.NONE })\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.NONE }, 45)\n\n    local trustLevel  = mob:getMainLvl()\n    local power       = trustLevel / 5\n    local spellDamage = trustLevel * math.floor((trustLevel + 1) / 10)\n\n    mob:addMod(xi.mod.MATT, power)\n    mob:addMod(xi.mod.MACC, power)\n    mob:addMod(xi.mod.HASTE_MAGIC, 1000) -- 10% Haste (Magic)\n\n    -- Shantotto's tier I spells scale up to mimic tier 2, 3, etc, spells.\n    mob:addMod(xi.mod.MAGIC_DAMAGE, spellDamage)\n\n    -- Shantotto has 100% melee hit rate always.\n    -- TODO: Add support for 'perfect accuracy' in c++ land and stop hacking her accuracy.\n    mob:addMod(xi.mod.ACC, 1000)\n\n    -- Shantotto II attack type is suposed to be 'typeless physical, like requiescat WS.'\n    mob:setMobSkillAttack(1163)\n\n    -- TODO: Her regular attacks have a big range (distance from mob, not AoE)\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 2500)\n\n    mob:addListener('WEAPONSKILL_USE', 'SHANTOTTO_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3740 then -- Final Exam\n            -- And yet again, the flames of life are snuffed out, and I'll say this--it was an out and out rout!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    -- Spellcast (occasionally)\n    mob:addListener('MAGIC_USE', 'SHANTOTTO_II_MAGIC', function(mobArg, target, spell, action)\n        if math.randomInt(1, 100) <= 33 then\n            -- Ohohohohoho!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_2)\n        end\n    end)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/shikaree_z.lua"]={["Path"]="scripts/actions/spells/trust/shikaree_z.lua",["SHA256"]="ae03754a7ff53c1c12ce505937a157574699c517df52a27ac7a90e00850850bf",["Text"]="-----------------------------------\n-- Trust: Shikaree Z\n-- Possesses MP+100%\n-- Uses Ancient Circle if the enemy is a dragon\n-- Super Jump is used when ShikareeZ is in the top enmity slot\n-- Gains 205 TP on hit; has high TP return on Jump (655 TP) and High Jump (1065 TP).\n-- TODO: Add/Apply MOD for HIGH_JUMP_TP_BONUS\n-- Holds TP to 2000 to try to close skillchains. (TODO)\n-- Saves Cure for party members under 50% HP or affected by Sleep\n-- Prioritizes Haste over other spells, except to cast Erase when Slow would prevent Haste.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    -- MPP mod migrated to sql/mob_pool_mods to apply at spawn\n    mob:addMod(xi.mod.STORETP, 174)\n    mob:addMod(xi.mod.JUMP_TP_BONUS, 164)\n\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HASTE })\n    mob:addGambit(ai.t.MASTER, { ai.c.STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.MASTER, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HASTE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 50 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.IS_ECOSYSTEM, xi.ecosystem.DRAGON }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.ANCIENT_CIRCLE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.JUMP })\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HIGH_JUMP })\n    mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SUPER_JUMP })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 2000)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/star_sibyl.lua"]={["Path"]="scripts/actions/spells/trust/star_sibyl.lua",["SHA256"]="7e83c6b4d88c5516ddbd17ac89fb1900fe9aaea9f9fbb1d6e50a6a87632fdfa3",["Text"]="-----------------------------------\n-- Trust: Star Sibyl\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.AJIDO_MARUJIDO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.SHANTOTTO] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.KUPIPI] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.KARAHA_BARUHA] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.SEMIH_LAFIHNA] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_MAGIC_ATTACK,\n        subPower = mob:getMainLvl(),\n        subIcon = xi.effect.GEO_MAGIC_ATK_BOOST,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 3 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/sylvie_uc.lua"]={["Path"]="scripts/actions/spells/trust/sylvie_uc.lua",["SHA256"]="328f82092ec2304c7b87c01bd8ebb44aecf0dcafc19877f34d258e57c1c09854",["Text"]="-----------------------------------\n-- Trust: Sylvie UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    local master = mob:getMaster()\n    if not master then\n        return\n    end\n\n    local mJob   = master:getMainJob()\n\n    -- Has Regain (50/tick) and uses Nott when MP falls below 66%.\n    -- cure IV cures 456 HP @99\n\n    mob:addMod(xi.mod.GEOMANCY_SKILL, 8 * mob:getMainLvl() + 1)\n    mob:addMod(xi.mod.INDI_DURATION, 180)\n    mob:addMod(xi.mod.REGAIN, 50)\n\n    if mob:getMainLvl() >= 99 then\n        mob:addMod(xi.mod.GEOMANCY_BONUS, 3)\n    end\n\n    mob:addGambit(ai.t.SELF, { { ai.c.MPP_LT, 66 }, { ai.c.LVL_GTE, 50 }, { ai.c.TP_GTE, 1000 } }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.NOTT })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.MASTER, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n\n    if mob:getMainLvl() >= 20 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.COLURE_ACTIVE }, { ai.r.MA, ai.s.BEST_INDI, xi.magic.spellFamily.NONE })\n    end\n\n    if mob:getMainLvl() >= 93 and mJob ~= xi.job.GEO then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.ENTRUST }, { ai.r.JA, ai.s.SPECIFIC, xi.jobAbility.ENTRUST })\n        mob:addGambit(ai.t.SELF, { ai.c.STATUS, xi.effect.ENTRUST }, { ai.r.MA, ai.s.ENTRUSTED, xi.magic.spellFamily.INDI_BUFF })\n    end\n\n    mob:addGambit(ai.t.MASTER, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HASTE })\n    mob:addGambit(ai.t.MELEE, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HASTE })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/tenzen.lua"]={["Path"]="scripts/actions/spells/trust/tenzen.lua",["SHA256"]="ad9d30787636d1a4efed1dc03f12b0deb155fd0f849d83b87731165e9d56c47c",["Text"]="-----------------------------------\n-- Trust: Tenzen\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.TENZEN_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Records of Eminence: Alter Ego: Tenzen\n    if caster:getEminenceProgress(935) then\n        xi.roe.onRecordTrigger(caster, 935)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.IROHA] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.HASSO }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HASSO })\n\n    mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.THIRD_EYE })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 1500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/tenzen_ii.lua"]={["Path"]="scripts/actions/spells/trust/tenzen_ii.lua",["SHA256"]="4a26e8acd0ab0566126bb0e5078495d601e46f8ed5b41d2ce934ec08f9f72f12",["Text"]="-----------------------------------\n-- Trust: Tenzen II\n-- Todo: Constantly adjusts his distance for optimal ranged damage (always shot from sweet spot).\n-- BIG Todo: make his TP gains per shot match retail at all levels\n-- Tenzen II Gets 252 TP per hit at lv 90+ ONLY, see https://www.bg-wiki.com/ffxi/BGWiki:Trusts#Tenzen_II\n-- While the changes in TP gain do happen at the levels a SAM would get a storeTP trait adjustment,\n-- no combination of STP and wDelay aligns with the TP change in a way that makes all the different amounts\n-- make any kind of sense. Some sort of override is seeded to SET his exact TP gain based on a level check.\n-- There's just no other way to be retail accurate while having his attack delay match retail.\n-- This also means retail unfairly nerfs his TP gains prior to level 90,\n-- as other ranged attackers have the amount at level one he doesn't until level 90.\n-- I can't help but wonder if he is simply bugged on retail and nobody ever realized it.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.TENZEN)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.PRISHE] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addListener('WEAPONSKILL_USE', 'TENZEN_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3542 then -- Oisoya\n            -- Epehemeral, fleeting, fading. You are but a memory\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    -- Ranged Attack as much as possible (limited by 'weapon' delay)\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.RATTACK, 0, 0 })\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.LONG_RANGE)\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.HIGHEST)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/teodor.lua"]={["Path"]="scripts/actions/spells/trust/teodor.lua",["SHA256"]="bff33f26b8f042916c684f64e4a126b76c33a4cb9d96ca44c95f533e1fa0af0b",["Text"]="-----------------------------------\n-- Trust: Teodor\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/trion.lua"]={["Path"]="scripts/actions/spells/trust/trion.lua",["SHA256"]="0be499c7cf0a84c3d10079130c4dc23842db804fc022ec34a514d17be0c663e3",["Text"]="-----------------------------------\n-- Trust: Trion\n-- Royal Bash is stronger than a normal Shield Bash.\n-- Royal Saviour is a secondary, stronger version of Sentinel. Trion alternates between this and the normal version of Sentinel.\n-- Trion tries to interrupt TP-abilities with Royal Bash.\n-- Uses TP randomly and does not try to skillchain.\n-- With his two defensive TP moves, he's not likely to interrupt skillchains much.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.CURILLA] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.RAHAL] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.HALVER] = xi.trust.messageOffset.TEAMWORK_3,\n    })\n\n    mob:setMobMod(xi.mobMod.CAN_SHIELD_BLOCK, 1)\n    mob:setMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    local lvl = mob:getMainLvl()\n    local shieldMasteryPower = 0\n\n    if lvl >= 96 then\n        shieldMasteryPower = 40\n    elseif lvl >= 75 then\n        shieldMasteryPower = 30\n    elseif lvl >= 50 then\n        shieldMasteryPower = 20\n    elseif lvl >= 25 then\n        shieldMasteryPower = 10\n    end\n\n    mob:setMod(xi.mod.SHIELD_MASTERY_TP, shieldMasteryPower)\n    mob:setMod(xi.mod.SHIELDBLOCKRATE, 35)\n    mob:addMod(xi.mod.SPELLINTERRUPT, 30)\n    mob:addMod(xi.mod.FASTCAST, 30)\n    mob:addMod(xi.mod.ENMITY, 15)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 10)\n    mob:addMod(xi.mod.MPP, 10)\n\n    if lvl >= 5 then\n        mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 15 then\n        mob:addGambit(ai.t.TARGET, { ai.l.OR(\n            { ai.c.CASTING_MA, 0 },\n            { ai.c.READYING_JA, 0 },\n            { ai.c.READYING_MS, 0 },\n            { ai.c.READYING_WS, 0 }) }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.ROYAL_BASH_TRUST }, 60)\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH      })\n    mob:addGambit(ai.t.PARTY,  { ai.c.HPP_LT,     75              }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.CURE })\n\n    mob:setTrustTPSkillSettings(ai.tp.RANDOM, ai.s.RANDOM, 1500)\n\n    mob:addListener('WEAPONSKILL_USE', 'TRION_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.ROYAL_SAVIOR_TRUST then -- Royal Savior\n            -- O great kings of the noble line of d'Oraguille, shield me from harm!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/uka_totlihn.lua"]={["Path"]="scripts/actions/spells/trust/uka_totlihn.lua",["SHA256"]="2d4bb3ae61f9a00cf9e59d66f89bb6c9128a935d386832914b9bc05f80df533a",["Text"]="-----------------------------------\n-- Trust: Uka Totlihn\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\n-- Define the main jobs with access to primary healing used to toggle Samba type\nlocal healingJobs =\n{\n    xi.job.WHM,\n    xi.job.RDM,\n    xi.job.SCH,\n    xi.job.PLD,\n}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.MUMOR   ] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ULLEGORE] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    -- Dynamic modifier that checks party member list on tick to apply synergy\n    mob:addListener('COMBAT_TICK', 'UKA_TOTLIHN_CTICK', function(mobArg)\n        local waltzPotencyBoost = 0\n        local party = mobArg:getMaster():getPartyWithTrusts()\n        for _, member in pairs(party) do\n            if member:getObjType() == xi.objType.TRUST then\n                if\n                    member:getTrustID() == xi.magic.spell.MUMOR or\n                    member:getTrustID() == xi.magic.spell.MUMOR_II\n                then\n                    waltzPotencyBoost = 10\n                end\n            end\n        end\n\n        -- Always set the boost, even if Mumor wasn't found.\n        -- This accounts for her being in the party and giving the boost\n        -- and also if she dies and the boost goes away.\n        mobArg:setMod(xi.mod.WALTZ_POTENCY, waltzPotencyBoost)\n    end)\n\n    for i = 1, #healingJobs do\n        local master  = mob:getMaster()\n        if\n            master and\n            master:getMainJob() == healingJobs[i]\n        then\n            mob:addGambit(ai.t.SELF, { ai.c.NO_SAMBA, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HASTE_SAMBA })\n        end\n    end\n\n    -- Step Interactions:\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.LETHARGIC_DAZE_5 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.QUICKSTEP }, 20)\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n\n    -- Ecosystem check to swap to Haste samba if the target is undead\n    mob:addGambit(ai.t.TARGET, { ai.c.IS_ECOSYSTEM, xi.ecosystem.UNDEAD }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HASTE_SAMBA })\n\n    -- Healing logic\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.HIGHEST_WALTZ, xi.ja.CURING_WALTZ })\n    mob:addGambit(ai.t.SELF, { ai.c.NO_SAMBA, 0 }, { ai.r.JA, ai.s.BEST_SAMBA, xi.ja.DRAIN_SAMBA })\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.WALTZABLE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HEALING_WALTZ })\n\n    -- TP use and return\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS, xi.effect.FINISHING_MOVE_5 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.REVERSE_FLOURISH }, 60)\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 2000)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ullegore.lua"]={["Path"]="scripts/actions/spells/trust/ullegore.lua",["SHA256"]="77745068dace0921cf61e76a653913615256cf6d9934818fc637d6cb46a46415",["Text"]="-----------------------------------\n-- Trust: Ullegore\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ulmia.lua"]={["Path"]="scripts/actions/spells/trust/ulmia.lua",["SHA256"]="dcebff86debf6b9a857b23d37334e5ef10e7b4039df1f2d438a727e0296bf8fb",["Text"]="-----------------------------------\n-- Trust: Ulmia\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.PRISHE] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.MILDAURION] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    -- TODO: BRD trusts need better logic and major overhaul, for now they compliment each other\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.MADRIGAL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.MADRIGAL })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.MINUET }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.VALOR_MINUET })\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.MID_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/valaineral.lua"]={["Path"]="scripts/actions/spells/trust/valaineral.lua",["SHA256"]="c8a39dd7d0f6d75634254028684204feb48bbc8a80df1ce7fb9eeb61e4356781",["Text"]="-----------------------------------\n-- Trust: Valaineral\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Records of Eminence: Alter Ego: Valaineral\n    if caster:getEminenceProgress(933) then\n        xi.roe.onRecordTrigger(caster, 933)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.CAN_SHIELD_BLOCK, 1)\n    mob:setMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    local lvl = mob:getMainLvl()\n    local shieldMasteryPower = 0\n\n    if lvl >= 96 then\n        shieldMasteryPower = 40\n    elseif lvl >= 75 then\n        shieldMasteryPower = 30\n    elseif lvl >= 50 then\n        shieldMasteryPower = 20\n    elseif lvl >= 25 then\n        shieldMasteryPower = 10\n    end\n\n    mob:setMod(xi.mod.SHIELD_MASTERY_TP, shieldMasteryPower)\n    mob:setMod(xi.mod.SHIELDBLOCKRATE, 35)\n    mob:addMod(xi.mod.SPELLINTERRUPT, 30)\n    mob:addMod(xi.mod.CURE_POTENCY, 50)\n    mob:addMod(xi.mod.FASTCAST, 30)\n    mob:addMod(xi.mod.REFRESH, 2)\n    mob:addMod(xi.mod.ENMITY, 25)\n    mob:addMod(xi.mod.DMG, -800) -- Damage Taken -8%\n    mob:addMod(xi.mod.HPP, 10)\n    mob:addMod(xi.mod.MPP, 20)\n\n    if lvl >= 1 then\n        mob:addGambit(ai.t.TARGET, { ai.c.VAL_URIEL_CHECK, 0 }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.URIEL_BLADE_1 })\n    end\n\n    if lvl >= 5 then\n        mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    if lvl >= 50 then\n        mob:addGambit(ai.t.SELF, { { ai.c.MPP_LT,         50             }, { ai.c.TP_GTE,     1000               } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CHIVALRY })\n        mob:addGambit(ai.t.SELF, { { ai.c.JA_ON_COOLDOWN, xi.ja.SENTINEL }, { ai.c.NOT_STATUS, xi.effect.SENTINEL } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DEFENDER })\n    end\n\n    if lvl >= 62 then\n        mob:addGambit(ai.t.TARGET, { ai.c.STATUS, xi.effect.MANAFONT    }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.RAMPART })\n        mob:addGambit(ai.t.TARGET, { ai.c.STATUS, xi.effect.CHAINSPELL  }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.RAMPART })\n        mob:addGambit(ai.t.TARGET, { ai.c.STATUS, xi.effect.ASTRAL_FLOW }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.RAMPART })\n    end\n\n    if lvl >= 70 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.MAJESTY }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.MAJESTY })\n    end\n\n    if lvl >= 75 then\n        mob:addGambit(ai.t.TARGET, { ai.c.CASTING_DEBUFF, 0               }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.FEALTY        })\n        mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS,     xi.effect.FLASH }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DIVINE_EMBLEM })\n    end\n\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.PROTECT  }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECT })\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH    }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH        })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.REPRISAL }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.REPRISAL     })\n    mob:addGambit(ai.t.PARTY,  { ai.c.HPP_LT,     50                 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE    })\n    mob:addGambit(ai.t.SELF,   { ai.c.HPP_LT,     70                 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE    })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.ENLIGHT  }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ENLIGHT      })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.PHALANX  }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PHALANX      })\n    mob:addGambit(ai.t.PARTY,  { ai.c.STATUS,     xi.effect.SLEEP_I  }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE         })\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.RANDOM, 2000)\n\n    mob:addListener('WEAPONSKILL_USE', 'VALAINERAL_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.URIEL_BLADE_1 then -- Uriel Blade\n            -- Let the Blade of the Conqueror once again bring glory to the Kingdom!\n            if math.randomInt(1, 100) <= 33 then\n                if target:getID() == skill:getPrimaryTargetID() then\n                    xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n                end\n            end\n\n            mobArg:setLocalVar('[Gambit]LastUrielTime', GetSystemTime())\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/volker.lua"]={["Path"]="scripts/actions/spells/trust/volker.lua",["SHA256"]="e5f3c0af35c2e889bda3df58ff8387ae63b72d0457bcabbc227bda459f46fad8",["Text"]="-----------------------------------\n-- Trust: Volker\n-- If there is a NIN, PLD, or RUN in the party, behaves as a damage dealer: Uses Aggressor, Berserk.\n-- If there are no other tanks in the party, behaves as a tank: Uses Defender, Retaliation.\n-- Uses Provoke in either role to maintain enmity as a tank or off-tank.\n-- Uses weapon skills at 2000 TP with Warrior's Charge if it's available; does not try to skillchain. (TODO)\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.NAJI] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.CID] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.KLARA] = xi.trust.messageOffset.TEAMWORK_3,\n    })\n\n    -- DD Mode\n    mob:addGambit(ai.t.SELF, { ai.c.PT_HAS_TANK, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK })\n    mob:addGambit(ai.t.SELF, { ai.c.PT_HAS_TANK, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.AGGRESSOR })\n    mob:addGambit(ai.t.TANK, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n\n    -- Tank Mode\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_PT_HAS_TANK, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_PT_HAS_TANK, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DEFENDER })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_PT_HAS_TANK, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.RETALIATION })\n\n    mob:addGambit(ai.t.MASTER, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n\n    -- TODO: Add Warriors Charge + WS Logic\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ygnas.lua"]={["Path"]="scripts/actions/spells/trust/ygnas.lua",["SHA256"]="848b95a416f581f902ab625ddef8be140abb23eee3b291d3e8005357f348351d",["Text"]="-----------------------------------\n-- Trust: Ygnas\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/yoran-oran_uc.lua"]={["Path"]="scripts/actions/spells/trust/yoran-oran_uc.lua",["SHA256"]="0ac32c2c4933c23ff8196521055bb6e2485a23a1e887f1701900b1175d60727f",["Text"]="-----------------------------------\n-- Trust: Yoran-Oran UC\n-- All changes made are from BGWiki and in game observations. Wiki says he has Fast Cast, but doesn't specify how much so it has been left out.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    -- TODO: Nott weaponskill needs implemented and logic added here for Yoran-Oran to use at 50% MP at level 50.\n    -- TODO: UC trusts are supposed to get bonuses depending on unity ranking. Needs research.\n    -- TODO: Custom spawn messages if Unity ranking is higher.\n    -- TODO: Figure out what level of Fast Cast he has.\n\n    mob:addMod(xi.mod.CURE_POTENCY, 50)\n    mob:addMod(xi.mod.REGAIN, 50)\n    mob:addMod(xi.mod.MPP, 15) -- TODO: This is supposed to increase with Unity rank, but I don't believe that's implemented so it is set to the minimum.\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.AFFLATUS_SOLACE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.AFFLATUS_SOLACE })\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE }) -- Prioritizes curing party members at lower HP%.\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.STONESKIN }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONESKIN })\n\n    mob:setAutoAttackEnabled(false)\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.LONG_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/zazarg.lua"]={["Path"]="scripts/actions/spells/trust/zazarg.lua",["SHA256"]="9cc9078bbf868e722d06af73348f5bc709dc6b82ef51279d694a6d9594d1388e",["Text"]="-----------------------------------\n-- Trust: Zazarg\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/zeid.lua"]={["Path"]="scripts/actions/spells/trust/zeid.lua",["SHA256"]="99d602c4a1db3c3de2390270928a1fd9e5063128ec799c40cccbf49ddb454499",["Text"]="-----------------------------------\n-- Trust: Zeid\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ZEID_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/zeid_ii.lua"]={["Path"]="scripts/actions/spells/trust/zeid_ii.lua",["SHA256"]="1b4b3ad1d6559bb9a43c72c1f8d5624519c0e3e56208a9ae279c316d898fe873",["Text"]="-----------------------------------\n-- Trust: Zeid II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ZEID)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.LION_II] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addListener('WEAPONSKILL_USE', 'ZEID_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 56 then -- Ground Strike\n            -- Never again will I lose sight of who I am\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    -- Stun all the things!\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    -- Non-stun things\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SOULEATER })\n\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.LAST_RESORT })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 3000)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/addle.lua"]={["Path"]="scripts/actions/spells/white/addle.lua",["SHA256"]="70c431e7546785b5e68e964519eb6ae1953c1d53df7f916ff565607d4a1d1944",["Text"]="-----------------------------------\n-- Spell: Addle\n-- Main effect: Increases the casting time of the target.\n-- Sub effect: Lowers target magic accuracy.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/aquaveil.lua"]={["Path"]="scripts/actions/spells/white/aquaveil.lua",["SHA256"]="2a67d07db92c44b4a0839cec09d43d6b416fbca9e4845de6901f9dca64fc2c71",["Text"]="-----------------------------------\n-- Spell: Aquaveil\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/arise.lua"]={["Path"]="scripts/actions/spells/white/arise.lua",["SHA256"]="2283fd0a4239145b95a1c9e1e3b93d1d5e552009ab8659f8358fe334b2e40b93",["Text"]="-----------------------------------\n-- Spell: Arise\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    -- Can't cast on living targets\n    if target:isAlive() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Only PCs should ever be blocked by the Raise/Tractor menu state\n    if target:isPC() and target:hasRaiseTractorMenu() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Non-PC targets must be explicitly raisable (behavior bit)\n    if\n        not target:isPC() and\n        bit.band(target:getBehavior(), xi.behavior.RAISABLE) == 0\n    then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:isPC() then\n        target:sendRaise(4)\n    end\n\n    spell:setMsg(xi.msg.basic.MAGIC_CASTS_ON)\n    return 4\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/aurorastorm.lua"]={["Path"]="scripts/actions/spells/white/aurorastorm.lua",["SHA256"]="ceca196955b2d1e4cd63305306a940f6f8ee35c7fd9cc9b8a68b315b812ce5f8",["Text"]="-----------------------------------\n-- Spell: Aurorastorm\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/auspice.lua"]={["Path"]="scripts/actions/spells/white/auspice.lua",["SHA256"]="4603db2bb4aaa005ea47ccb59a76c8dc4fd498f4c7132519f7e8394ce37dd37e",["Text"]="-----------------------------------\n-- Spell: Auspice\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/banish.lua"]={["Path"]="scripts/actions/spells/white/banish.lua",["SHA256"]="83fef5937ef545b5222118238a6b59c60c4a8041226a0015e70982c6cbd1fa06",["Text"]="-----------------------------------\n-- Spell: Banish\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/banish_ii.lua"]={["Path"]="scripts/actions/spells/white/banish_ii.lua",["SHA256"]="a4616d1cae1a086b341a1d224d5ecbbc6c4b7aece4ad7afd2bb950d449aa73c3",["Text"]="-----------------------------------\n-- Spell: Banish II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/banish_iii.lua"]={["Path"]="scripts/actions/spells/white/banish_iii.lua",["SHA256"]="15da3d3863cb6abe4ec3a9081bb317d7f354d20fa559d1fb93a82a5121619cb5",["Text"]="-----------------------------------\n-- Spell: Banish III\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"}};
